import {COUNTRIES,LANGUAGES,PRIORITIES,STAGES,BENEFITS,TVH,country,seed,parisDate,isoLocal} from './data.js';
import {normalizeId,validId,active,people,waiting,ready,priority,filtered,record,availability,assignmentWarnings,assign,moveStage,archive,reopen,createCase,validateState,parseGPS} from './core.js';
import {ControlMap,searchPlace,hasPoint} from './map.js';
const KEY='manager-control-demo-v1';
const paths={map:'<path d="m3 6 6-3 6 3 6-3v15l-6 3-6-3-6 3z"/><path d="M9 3v15M15 6v15"/>',truck:'<path d="M3 5h12v12H3zM15 9h4l3 5v3h-7"/><circle cx="7" cy="18" r="2"/><circle cx="18" cy="18" r="2"/>',flow:'<circle cx="5" cy="5" r="2"/><circle cx="19" cy="6" r="2"/><circle cx="12" cy="19" r="2"/><path d="m7 5 10 1M6 7l5 10M18 8l-5 9"/>',files:'<rect x="4" y="5" width="16" height="16" rx="2"/><path d="M8 2h8M8 10h8M8 14h8M8 18h4"/>',team:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-4a6 6 0 0 1 12 0v4M16 4a3 3 0 0 1 0 6M21 21v-4a6 6 0 0 0-4-5"/>',chart:'<path d="M4 3v18h17M8 17v-5M13 17V7M18 17V4"/>',archive:'<rect x="3" y="4" width="18" height="4" rx="1"/><path d="M5 8v12h14V8M9 12h6"/>',plus:'<path d="M12 5v14M5 12h14"/>',chevron:'<path d="m9 5 7 7-7 7"/>',bell:'<path d="M4 17h16l-2-4V9a6 6 0 0 0-12 0v4zM10 21h4"/>',settings:'<path d="m12 3 3 2 3 1 1 4 2 2-2 2-1 4-3 1-3 2-3-2-3-1-1-4-2-2 2-2 1-4 3-1z"/><circle cx="12" cy="12" r="3"/>',filter:'<path d="M3 4h18l-7 8v7l-4 2v-9z"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',check:'<path d="m5 12 4 4L19 6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',pin:'<path d="M19 10c0 6-7 11-7 11S5 16 5 10a7 7 0 0 1 14 0z"/><circle cx="12" cy="10" r="2"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',upload:'<path d="M12 16V4m-5 5 5-5 5 5M4 17v4h16v-4"/>',success:'<circle cx="12" cy="12" r="9"/><path d="m7 12 3 3 7-7"/>',window:'<rect x="3" y="3" width="18" height="18" rx="3"/><path d="M3 8h18M7 5h.1M10 5h.1"/>',shield:'<path d="m12 2 9 4v6c0 6-9 10-9 10S3 18 3 12V6zM8 12l3 3 5-6"/>',globe:'<circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18"/>'};
paths.person='<circle cx="12" cy="5" r="3"/><path d="M7 21v-7a5 5 0 0 1 10 0v7M12 14v7"/>';paths.child='<circle cx="12" cy="7" r="2.5"/><path d="m6 13 6-2 6 2M12 11v6m0 0-3 4m3-4 3 4"/>';paths.pet='<circle cx="6" cy="7" r="2"/><circle cx="18" cy="7" r="2"/><circle cx="10" cy="4" r="1.5"/><circle cx="14" cy="4" r="1.5"/><path d="M7 16c0-7 10-7 10 0 0 5-3 3-5 3s-5 2-5-3z"/>';
const icon=(n)=>'<svg class="i" viewBox="0 0 24 24" aria-hidden="true">'+(paths[n]||paths.files)+'</svg>';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
let storageError='';let state;
try{state=localStorage.getItem(KEY)?validateState(JSON.parse(localStorage.getItem(KEY))):seed();}catch{state=seed();storageError='Sauvegarde locale illisible : démonstration chargée sans écraser la sauvegarde existante. Exportez avant de réinitialiser.'}
let view=new URLSearchParams(location.search).get('view')==='agent'?'agent':'map';
if(view==='agent')document.querySelector('link[rel=manifest]').href='./manifest-agent.webmanifest';
let filters={country:'',agent:'',priority:'',stage:'',type:'',q:'',from:'',to:''};
let map=null,completed=false,flowType='vehicles',dossierMode='list',teamMode='assign',planningDate=parisDate(),agentQuery='',agentLanguage='',agentAvailability='',agentService='',selected=null,editing=null,agentEditing=null,agentLoadedId=null,modalClose=null,storageRevision=0,draftRevision=0;
const pageNames={map:'Carte des opérations',tvh:'Transports de véhicules',flux:'Flux internationaux',cases:'Dossiers ETR',teams:'Équipes & affectations',dashboard:'Dashboard',archives:'Archives'};
let toastTimer;let pointerDrag=null,suppressClick=false;
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.className='show'+(error?' error':'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.className='',5500)}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageRevision++;storageError='';return true}catch{storageError='Stockage local indisponible ou saturé. Exportez vos données JSON avant de quitter cette page.';toast(storageError,true);return false}}
function commit(message){const ok=save();render();if(message)toast(ok?message:message+' · en mémoire uniquement',!ok)}
function badge(d){const p=priority(d,state.settings);return '<span class="priority-badge '+p.key+'" title="'+esc(p.reason)+'"><span class="dot '+p.key+'"></span>'+PRIORITIES[p.key].label+'</span>'}
function date(v,short=false){return v?new Intl.DateTimeFormat('fr-FR',{timeZone:'Europe/Paris',day:'2-digit',month:'short',...(short?{}:{hour:'2-digit',minute:'2-digit'})}).format(new Date(v)):'Non renseignée'}
function age(d){const h=Math.max(0,Math.floor((Date.now()-Date.parse(d.opened))/3600000));return h<24?h+' h':Math.floor(h/24)+' j '+h%24+' h'}
const agentName=id=>state.agents.find(a=>a.id===id)?.name||'Non affecté';
const opt=(value,label,current)=>'<option value="'+esc(value)+'"'+(value===current?' selected':'')+'>'+esc(label)+'</option>';
const options=(list,current)=>list.map(v=>opt(v,v,current)).join('');
const countryOptions=(current,all=false)=>(all?opt('','Tous les pays',current):'')+COUNTRIES.map(c=>opt(c.code,c.flag+' '+c.name,current)).join('');
const agentOptions=(current,all=false)=>(all?opt('','Tous les chargés',current):opt('','Non affecté',current))+state.agents.map(a=>opt(a.id,a.name,current)).join('');
const field=(label,name,type,value,extra='')=>'<label class="field">'+label+'<input name="'+name+'" type="'+type+'" value="'+esc(value)+'" '+extra+'></label>';
const select=(label,name,opts,extra='')=>'<label class="field">'+label+'<select name="'+name+'" '+extra+'>'+opts+'</select></label>';
function setView(v){if(v==='agent'){window.open('./?view=agent','manager-control-agent','width=420,height=810,resizable=yes,scrollbars=yes');return}view=v;render();window.scrollTo({top:0,behavior:'instant'})}
function kpis(rows){const critical=rows.filter(d=>priority(d,state.settings).key==='critical').length,tvh=rows.filter(d=>d.tvh==='En cours').length,benef=rows.filter(waiting).reduce((n,d)=>n+d.groups.filter(g=>['Sur place','En attente de solution'].includes(g.status)).reduce((a,g)=>a+g.men+g.women+g.children,0),0);
 const entries=[['Dossiers actifs',rows.length,'files',COUNTRIES.filter(c=>rows.some(d=>d.country===c.code)).length+' pays représentés',''],['Actions en retard',rows.filter(d=>d.due&&Date.parse(d.due)<Date.now()).length,'clock','Échéances à traiter','alert'],['Bénéficiaires en attente',benef,'team','Sur place ou sans solution',''],['TVH en cours',tvh,'truck','Transports à superviser','green'],['Dossiers critiques',critical,'shield','Décision managériale','alert']];
 return '<div class="kpis">'+entries.map(([l,v,i,n,c])=>'<div class="kpi '+c+'"><div><span class="label">'+l+'</span><strong>'+v+'</strong><small>'+n+'</small></div><span class="kpi-icon">'+icon(i)+'</span></div>').join('')+'</div>';
}
function filterBar(){return '<div class="filters"><span class="filter-icon">'+icon('filter')+'</span><select aria-label="Filtrer par pays" data-filter="country" class="'+(filters.country?'filter-active':'')+'">'+countryOptions(filters.country,true)+'</select><select aria-label="Filtrer par chargé" data-filter="agent">'+agentOptions(filters.agent,true)+opt('none','Non affecté',filters.agent)+'</select><select aria-label="Filtrer par priorité" data-filter="priority">'+opt('','Toutes priorités',filters.priority)+Object.entries(PRIORITIES).map(([k,p])=>opt(k,p.label,filters.priority)).join('')+'</select><select aria-label="Filtrer par étape" data-filter="stage">'+opt('','Toutes les étapes',filters.stage)+options(STAGES,filters.stage)+'</select><select aria-label="Filtrer par assistance" data-filter="type">'+opt('','Toute assistance',filters.type)+options(['Panne','Accident'],filters.type)+'</select><input aria-label="Rechercher un dossier" placeholder="N° dossier, lieu, action…" data-filter="q" value="'+esc(filters.q)+'"><button class="small ghost" data-action="dates" title="Filtrer par dates">'+icon('clock')+'</button><button class="small ghost" data-action="reset-filters" aria-label="Réinitialiser les filtres">'+icon('close')+'</button></div>'}
function shell(){const nav=[['map','map','CARTE'],['tvh','truck','TVH'],['flux','flow','FLUX'],['cases','files','DOSSIERS'],['teams','team','ÉQUIPES & AFFECTATIONS'],['dashboard','chart','DASHBOARD'],['archives','archive','ARCHIVES']];
 return '<div class="shell"><aside class="sidebar"><div class="brand"><div class="brand-symbol">'+icon('chart')+'</div><div class="brand-name">Manager<br>Control<small>Supervision ETR</small></div></div><div class="nav-label">ESPACE OPÉRATIONS</div><nav class="nav" aria-label="Navigation principale">'+nav.map(([v,i,l])=>'<button data-view="'+v+'" class="'+(view===v?'active':'')+'" title="'+l+'" aria-label="'+l+'">'+icon(i)+'<span>'+l+'</span></button>').join('')+'</nav><div class="side-bottom"><a class="side-agent" href="./?view=agent" target="_blank" data-action="agent-window">'+icon('window')+'<span>Interface chargé ↗</span></a><button data-action="settings" class="ghost" style="color:#a4b4cf;font-size:11px;justify-content:flex-start">'+icon('settings')+'<span>Paramètres & données</span></button><div class="side-note"><span class="live-dot"></span>Laboratoire de démonstration<br><br>Données fictives · stockage local</div></div></aside><section class="workspace"><header class="topbar"><div class="breadcrumb">Supervision internationale '+icon('chevron')+' <b>'+pageNames[view]+'</b></div><div class="top-actions"><span class="demo">DÉMONSTRATION</span><button class="ghost small" data-action="settings" title="Paramètres & données" aria-label="Paramètres & données">'+icon('settings')+'</button><div class="user"><span class="avatar">MC</span><div>Superviseur<small class="muted" style="display:block">Accès démo manager</small></div></div></div></header><main class="main"><div class="page-heading"><div><h1>'+pageNames[view]+'</h1><p>'+({map:'Vue internationale · ETR, bénéficiaires et transports',tvh:'Prise en charge, parcours et relivraison des véhicules',flux:'Concentrations, rapatriements et coopération entre équipes',cases:'Un suivi distinct pour le véhicule et les bénéficiaires',teams:'Répartition, disponibilités et continuité de service',dashboard:'Indicateurs calculés sur les dossiers de démonstration',archives:'Dossiers clôturés, conservés et réouvrables'}[view])+'</p></div><div class="actions"><button class="small" data-action="export">'+icon('download')+' Exporter</button><button class="primary" data-action="new">'+icon('plus')+' Nouveau dossier</button></div></div>'+ (storageError?'<div class="notice error">'+esc(storageError)+'</div>':'')+'<div id="content"></div><footer class="bottom-note"><span><span class="live-dot"></span>Stockage local à ce navigateur · aucune synchronisation entre appareils</span><span>72 scénarios initiaux · 24 pays · Horaires Europe/Paris</span></footer></main></section></div>';
}
function render(){
 map?.destroy();map=null;
 if(view==='agent'){renderAgent();return}
 $('#app').innerHTML=shell();const rows=filtered(state,filters,view==='archives');let content='';
 if(['map','tvh','flux'].includes(view))content=renderMap(rows);
 if(view==='cases')content=renderCases(rows);
 if(view==='teams')content=renderTeams(rows);
 if(view==='dashboard')content=renderDashboard(rows);
 if(view==='archives')content=filterBar()+'<div class="notice">'+icon('success')+' Les dossiers archivés sont conservés avec leur historique. La réouverture les replace dans les vues actives.</div>'+caseTable(rows,true);
 $('#content').innerHTML=content;
 if(['map','tvh','flux'].includes(view)){
  map=new ControlMap($('#map'),{selectCountry:code=>{filters.country=code;render();map?.focus(code)},openCase,onMessage:(msg,kind)=>{if(kind==='route'){if($('#route-message'))$('#route-message').textContent=msg}else toast(msg,kind==='error')}});
  map.update(state,rows,view,{completed,flow:flowType});if(filters.country)map.focus(filters.country);
 }
}
function renderMap(rows){
 const ranking={critical:0,urgent:1,follow:2,normal:3},alerts=[...rows].sort((a,b)=>ranking[priority(a,state.settings).key]-ranking[priority(b,state.settings).key]).slice(0,4);
 const controls=view==='tvh'?'<label class="check-line"><input type="checkbox" id="completed" '+(completed?'checked':'')+'> Parcours livrés</label>':view==='flux'?'<select id="flow-type" aria-label="Type de flux" style="width:140px;font-size:11px">'+opt('vehicles','Véhicules',flowType)+opt('people','Bénéficiaires',flowType)+'</select>':'<button class="small ghost" data-action="search-map">'+icon('search')+' Rechercher un lieu</button>';
 let out=kpis(rows)+filterBar()+'<div class="map-grid"><section class="panel map-shell"><div class="map-toolbar"><div class="segments"><button data-view="map" class="'+(view==='map'?'selected':'')+'">'+icon('map')+' Dossiers</button><button data-view="tvh" class="'+(view==='tvh'?'selected':'')+'">'+icon('truck')+' TVH</button><button data-view="flux" class="'+(view==='flux'?'selected':'')+'">'+icon('flow')+' Flux</button></div>'+controls+'</div><div id="map" class="map" aria-label="Carte interactive des dossiers ETR"></div><div class="map-caption"><div class="legend">'+Object.entries(PRIORITIES).map(([k,p])=>'<span><i class="dot '+k+'"></i>'+p.label+'</span>').join('')+'</div><span>'+(filters.country?country(filters.country).name+' · filtre actif':'Survolez un pays · cliquez pour filtrer')+'</span></div></section><aside class="panel attention"><div class="panel-header"><h2>À votre attention</h2><span class="attention-count">'+rows.filter(d=>['critical','urgent'].includes(priority(d,state.settings).key)).length+'</span></div><div class="attention-list">'+alerts.map(d=>'<article class="attention-card" tabindex="0" role="button" data-open="'+esc(d.id)+'"><div class="attention-top"><b>'+esc(d.id)+'</b>'+badge(d)+'</div><p>'+esc(d.action)+'</p><span class="attention-meta">'+country(d.country).flag+' '+esc(d.location?.label.split(' — ')[0]||'Non localisé')+' · '+age(d)+'</span></article>').join('')+(!rows.length?'<div class="empty">Aucun dossier</div>':'')+'</div><div class="attention-footer">Priorités et étapes véhicule sont distinctes.</div></aside></div>';
 if(view==='tvh')out+='<div class="notice" id="route-message">Calcul des parcours à la demande · positions des étiquettes EN COURS simulées, sans suivi GPS réel. Les TVH en attente n’affichent aucun trajet.</div>';
 if(view==='flux')out+='<div class="notice">Les liens de flux sont schématiques. Ils ne constituent ni un itinéraire ni une décision logistique.</div>'+flowPanels(rows);
 const unlocated=rows.filter(d=>!hasPoint(d.location));if(unlocated.length)out+='<div class="notice warn">'+unlocated.length+' dossier(s) sans position confirmée, accessibles dans DOSSIERS : '+unlocated.map(d=>'<button class="link-button" data-open="'+esc(d.id)+'">'+esc(d.id)+'</button>').join(', ')+'</div>';
 return out+'<section class="panel below"><div class="panel-header"><h2>Répartition de l’équipe</h2><button class="small ghost" data-view="teams">Voir les affectations '+icon('chevron')+'</button></div><div class="team-strip">'+state.agents.slice(0,4).map(a=>{const n=rows.filter(d=>d.agent===a.id).length,av=availability(a);return '<div class="team-summary"><div class="team-line"><b>'+esc(a.name)+'</b><span class="'+(av.ok?'available':'unavailable')+'">'+av.label+'</span></div><div class="progress-track"><div class="progress-fill" style="width:'+Math.min(100,n/a.capacity*100)+'%"></div></div><div class="team-line muted"><span>'+n+' dossiers / repère '+a.capacity+'</span><span>'+a.languages.map(l=>l.toUpperCase()).join(' · ')+'</span></div></div>'}).join('')+'</div></section>';
}
function caseTable(rows,archived=false){return '<section class="panel"><div class="panel-header"><h2>'+rows.length+' dossier'+(rows.length>1?'s':'')+'</h2><span class="muted" style="font-size:10px">'+(archived?'Date de clôture conservée':'Cliquez sur un numéro pour ouvrir la fiche')+'</span></div><div class="table-wrap"><table><thead><tr><th>DOSSIER</th><th>PAYS / LIEU</th><th>PRIORITÉ</th><th>VÉHICULE / TVH</th><th>BÉNÉFICIAIRES</th><th>CHARGÉ</th><th>'+(archived?'CLÔTURE':'PROCHAINE ACTION')+'</th><th></th></tr></thead><tbody>'+rows.map(d=>'<tr><td><button class="link-button" data-open="'+esc(d.id)+'">'+esc(d.id)+'</button><small class="muted" style="display:block">'+d.type+' · '+age(d)+'</small></td><td>'+country(d.country).flag+' '+country(d.country).name+'<small class="muted" style="display:block">'+esc(d.location?.label.split(' — ')[0]||'Non localisé')+'</small></td><td>'+badge(d)+'</td><td>'+d.stage+'<small class="muted" style="display:block">TVH · '+d.tvh+'</small></td><td>'+people(d)+' pers. '+(waiting(d)?'<span class="priority-badge urgent">En attente</span>':'')+'<small class="muted" style="display:block">'+esc(d.groups.length>1?d.groups.length+' sous-groupes':d.groups[0].status)+'</small></td><td>'+esc(agentName(d.agent))+'</td><td>'+(archived?date(d.closed):esc(d.action)+'<small class="muted" style="display:block">'+date(d.due)+'</small>')+'</td><td><button class="small ghost" data-action="'+(archived?'reopen':'archive')+'" data-id="'+esc(d.id)+'" aria-label="'+(archived?'Réouvrir':'Archiver')+' '+esc(d.id)+'">'+icon(archived?'plus':'archive')+'</button></td></tr>').join('')+'</tbody></table></div>'+(!rows.length?'<div class="empty">Aucun dossier ne correspond aux filtres.</div>':'')+'</section>'}
function card(d){return '<article draggable="true" class="case-card" data-case="'+esc(d.id)+'" tabindex="0"><div class="row"><button class="link-button" data-open="'+esc(d.id)+'">'+esc(d.id)+'</button>'+badge(d)+'</div><p>'+country(d.country).flag+' '+esc(d.location?.label.split(' — ')[0]||country(d.country).name)+'</p><small>'+esc(d.action)+' · '+date(d.due,true)+'</small></article>'}
function archiveZone(){return '<div class="archive-drop drop" data-drop="archive">'+icon('success')+'<div><b>Archiver un dossier terminé</b><small style="display:block">Glissez ici un dossier · confirmation avant clôture · également disponible dans la fiche</small></div></div>'}
function renderCases(rows){return filterBar()+'<div class="actions" style="margin-bottom:16px"><div class="segments"><button data-action="cases-list" class="'+(dossierMode==='list'?'selected':'')+'">Liste</button><button data-action="cases-kanban" class="'+(dossierMode==='kanban'?'selected':'')+'">Pipeline véhicule</button></div><span class="muted" style="font-size:11px">Les bénéficiaires conservent leur suivi propre.</span></div>'+(dossierMode==='list'?caseTable(rows):'<div class="kanban">'+STAGES.map(s=>'<section class="kan-col drop" data-drop="stage" data-stage="'+s+'"><div class="col-title">'+s+' <span class="tag">'+rows.filter(d=>d.stage===s).length+'</span></div>'+rows.filter(d=>d.stage===s).map(card).join('')+'</section>').join('')+'</div>')+archiveZone()}
function renderTeams(rows){const list=state.agents.filter(a=>a.name.toLowerCase().includes(agentQuery.toLowerCase())&&(!agentLanguage||a.languages.includes(agentLanguage))&&(!agentService||a.service===agentService)&&(!agentAvailability||(availability(a).ok?'yes':'no')===agentAvailability));
 return filterBar()+'<div class="actions" style="margin-bottom:16px"><div class="segments"><button data-action="teams-assign" class="'+(teamMode==='assign'?'selected':'')+'">Affectations</button><button data-action="teams-planning" class="'+(teamMode==='planning'?'selected':'')+'">Planning & transmissions</button></div></div><div class="filters"><input id="agent-query" value="'+esc(agentQuery)+'" placeholder="Nom du collaborateur" aria-label="Nom du collaborateur"><select id="agent-language" aria-label="Langue du collaborateur">'+opt('','Toutes les langues',agentLanguage)+Object.entries(LANGUAGES).map(([k,v])=>opt(k,v,agentLanguage)).join('')+'</select><select id="agent-availability" aria-label="Disponibilité du collaborateur">'+opt('','Toute disponibilité',agentAvailability)+opt('yes','Disponibles',agentAvailability)+opt('no','Indisponibles',agentAvailability)+'</select><select id="agent-service" aria-label="Service du collaborateur">'+opt('','Tous les services',agentService)+[...new Set(state.agents.map(a=>a.service))].map(v=>opt(v,v,agentService)).join('')+'</select><button class="small" data-action="import-planning">'+icon('upload')+' Import planning</button><button class="small ghost" data-action="planning-template">Modèle CSV</button></div>'+(teamMode==='planning'?renderPlanning(list,rows):'<div class="teams-board"><section class="unassigned drop" data-drop="assign" data-agent=""><div class="col-title">Non affectés <span class="tag">'+rows.filter(d=>!d.agent).length+'</span></div>'+rows.filter(d=>!d.agent).map(card).join('')+'</section><div class="agents-grid">'+list.map(a=>{const assigned=rows.filter(d=>d.agent===a.id),total=active(state).filter(d=>d.agent===a.id).length,av=availability(a);return '<section class="agent-card drop" data-drop="assign" data-agent="'+a.id+'"><header><span class="avatar">'+a.name.split(' ').map(w=>w[0]).join('')+'</span><div><h3>'+esc(a.name)+'</h3><span class="'+(av.ok?'available':'unavailable')+'">'+av.label+'</span></div></header><div class="tags">'+a.languages.map(l=>'<span class="tag">'+LANGUAGES[l]+'</span>').join('')+'</div><span class="muted" style="font-size:10px">'+esc(a.service)+'</span><div class="load-line"><span>'+total+' dossiers actifs</span><span>Capacité indicative '+a.capacity+'</span></div><div class="progress-track"><div class="progress-fill" style="width:'+Math.min(100,total/a.capacity*100)+'%;background:'+(total>a.capacity?'#db9019':'')+'"></div></div><div class="agent-dossiers">'+assigned.map(card).join('')+(!assigned.length?'<small class="muted">Glissez un dossier ici</small>':'')+'</div><button class="ghost small" data-action="edit-agent" data-id="'+a.id+'">Profil & langues</button></section>'}).join('')+'</div></div>')+'<div class="notice">Charge indicative : 1 point par dossier + 1 si urgent/critique + 1 si TVH en cours. Ce repère aide à répartir le travail ; il ne mesure pas la productivité. Les contrôles utilisent le planning en heure de Paris.</div>'+archiveZone();
}
function shiftBar(sh){if(!sh||sh.unavailable)return '<span class="muted">'+esc(sh?.reason||'Non renseigné')+'</span>';const p=t=>{const [h,m]=t.split(':').map(Number);return(h+m/60)/24*100},a=p(sh.start),b=p(sh.end),bs=p(sh.breakStart),be=p(sh.breakEnd);return '<div class="shift-bar">'+(b<a?'<span class="shift-time" style="left:0;width:'+b+'%"></span><span class="shift-time" style="left:'+a+'%;right:0"></span>':'<span class="shift-time" style="left:'+a+'%;width:'+(b-a)+'%"></span>')+'<span class="break-time" style="left:'+bs+'%;width:'+Math.max(0,be-bs)+'%"></span></div>'}
function renderPlanning(list,rows){return '<section class="panel"><div class="planning-tools"><label class="field">Journée de prise de poste<input type="date" id="planning-date" value="'+planningDate+'"></label><span class="muted" style="font-size:11px;align-self:center">Bleu : service · Jaune : pause · Cliquez sur Modifier pour corriger une journée.</span></div><div class="table-wrap"><table class="calendar"><thead><tr><th>COLLABORATEUR</th><th>00h</th><th colspan="2">06h — 12h — 18h — 24h</th><th>HORAIRES / PAUSE</th><th>DOSSIERS / CHARGE</th><th>TRANSMISSION</th><th></th></tr></thead><tbody>'+list.map(a=>{const sh=a.schedule.find(s=>s.date===planningDate),mine=rows.filter(d=>d.agent===a.id),points=mine.reduce((n,d)=>n+1+(['urgent','critical'].includes(priority(d,state.settings).key)?1:0)+(d.tvh==='En cours'?1:0),0);return '<tr><td><b>'+esc(a.name)+'</b><small class="muted" style="display:block">'+esc(a.service)+'</small></td><td colspan="3" style="min-width:230px">'+shiftBar(sh)+'</td><td>'+(sh&&!sh.unavailable?sh.start+' – '+sh.end+'<small class="muted" style="display:block">Pause '+sh.breakStart+' – '+sh.breakEnd+'</small>':'Repos / non renseigné')+'</td><td>'+mine.length+' dossiers · '+points+' points</td><td><button class="small" data-action="handover" data-id="'+a.id+'">Préparer ('+mine.length+')</button></td><td><button class="small ghost" data-action="edit-shift" data-id="'+a.id+'">Modifier</button></td></tr>'}).join('')+'</tbody></table></div></section>'}
function flowPanels(rows){const groups=new Map();rows.filter(d=>d.tvh==='En attente'||d.tvh==='En cours').forEach(d=>{const key=d.country+'>'+d.destination?.country;const list=groups.get(key)||[];list.push(d);groups.set(key,list)});
 const mutual=[...groups].filter(([,list])=>list.length>1);const cooperation=COUNTRIES.map(c=>{const ds=rows.filter(d=>d.country===c.code),needs=[...new Set(ds.map(d=>d.language))];return {c,ds,needs}}).filter(x=>x.ds.length);
 return '<div class="dashboard-grid below"><section class="panel"><div class="panel-header"><h2>Possibilités de mutualisation</h2><span class="tag">À vérifier</span></div>'+(mutual.length?mutual.map(([,ds])=>'<div class="flow-item"><b>'+country(ds[0].country).flag+' '+country(ds[0].country).name+' → '+esc(country(ds[0].destination?.country)?.name||'Destination à confirmer')+'</b><p>'+ds.map(d=>'<button class="link-button" data-open="'+d.id+'">'+d.id+'</button>').join(' · ')+'</p><small>Départs au sein du même pays : vérifier les villes, délais, capacités et destinations exactes avant toute organisation.</small></div>').join(''):'<div class="empty">Aucun groupe de départ / destination commun dans ce filtre.</div>')+'</section><section class="panel"><div class="panel-header"><h2>Coopération & langues réellement attribuées</h2></div>'+cooperation.map(({c,ds,needs})=>'<div class="flow-item"><b>'+c.flag+' '+c.name+' · '+ds.length+' dossiers</b>'+needs.map(l=>{const capable=state.agents.filter(a=>a.languages.includes(l)),av=capable.filter(a=>availability(a).ok);return '<small>'+LANGUAGES[l]+' : '+av.length+' disponible(s) / '+capable.length+' compétent(s)'+(av.length?' · '+av.map(a=>esc(a.name)).join(', '):' · relais linguistique à organiser')+'</small>'}).join('')+'</div>').join('')+'</section></div>';
}
function bars(entries,total,color='#4c89ef'){return entries.map(([label,n])=>'<div class="bar-row"><span>'+esc(label)+'</span><div class="progress-track"><div class="progress-fill" style="width:'+(n/Math.max(1,total)*100)+'%;background:'+color+'"></div></div><b>'+n+'</b></div>').join('')}
function renderDashboard(rows){const perCountry=COUNTRIES.map(c=>[c.flag+' '+c.name,rows.filter(d=>d.country===c.code).length]).filter(x=>x[1]).sort((a,b)=>b[1]-a[1]),perAgent=state.agents.map(a=>[a.name,rows.filter(d=>d.agent===a.id).length]);perAgent.push(['Non affectés',rows.filter(d=>!d.agent).length]);
 const days=Array.from({length:7},(_,i)=>{const dt=new Date();dt.setDate(dt.getDate()+i-6);const day=parisDate(dt);return {day,label:date(dt,true),opened:rows.filter(d=>parisDate(new Date(d.opened))===day).length,closed:filtered(state,filters,true).filter(d=>parisDate(new Date(d.closed))===day).length}});const max=Math.max(1,...days.map(d=>Math.max(d.opened,d.closed)));const line=(key)=>days.map((d,i)=>(30+i*75)+','+(150-d[key]/max*120)).join(' ');
 return kpis(rows)+filterBar()+'<div class="dashboard-grid"><section class="panel"><div class="panel-header"><h2>Évolution sur 7 jours</h2><span class="tag">Données du filtre</span></div><div class="chart"><svg viewBox="0 0 520 180" role="img" aria-label="Ouvertures et clôtures sur sept jours"><path d="M25 150h470M25 90h470M25 30h470" fill="none" stroke="#e6ecf4"/><polyline points="'+line('opened')+'" fill="none" stroke="#3e80f0" stroke-width="3"/><polyline points="'+line('closed')+'" fill="none" stroke="#26a680" stroke-width="2"/>'+days.map((d,i)=>'<text x="'+(30+i*75)+'" y="173" font-size="9" fill="#8795aa" text-anchor="middle">'+esc(d.label)+'</text>').join('')+'</svg><div class="chart-legend">Bleu : ouvertures actives du filtre · Vert : clôtures archivées du filtre</div>'+days.map(d=>'<span class="tag">'+d.label+' : '+d.opened+' / '+d.closed+'</span>').join(' ')+'</div></section><section class="panel"><div class="panel-header"><h2>Priorités & suivi</h2></div><div class="chart">'+Object.entries(PRIORITIES).map(([k,p])=>bars([[p.label,rows.filter(d=>priority(d,state.settings).key===k).length]],rows.length,p.color)).join('')+'<div class="notice">TVH en attente : <b>'+rows.filter(d=>d.tvh==='En attente').length+'</b> · Dossiers archivés : <b>'+filtered(state,filters,true).length+'</b> · Actions à venir : <b>'+rows.filter(d=>d.due&&Date.parse(d.due)>=Date.now()).length+'</b></div></div></section><section class="panel"><div class="panel-header"><h2>Dossiers par pays</h2></div><div class="chart">'+bars(perCountry,Math.max(...perCountry.map(x=>x[1]),1))+'</div></section><section class="panel"><div class="panel-header"><h2>Dossiers par chargé</h2></div><div class="chart">'+bars(perAgent,Math.max(...perAgent.map(x=>x[1]),1))+'</div></section></div>'+flowPanels(rows);
}
function showModal(html,onMount){$('#modal-root').innerHTML='<div class="modal-shade"><section class="modal" role="dialog" aria-modal="true">'+html+'</section></div>';modalClose=null;onMount?.();setTimeout(()=>$('input,button,select',$('#modal-root'))?.focus(),0)}
function closeModal(){const cb=modalClose;$('#modal-root').innerHTML='';modalClose=null;cb?.()}
function confirmAction(title,description,callback,justify=false){showModal('<h2>'+esc(title)+'</h2><p>'+esc(description)+'</p>'+(justify?'<label class="field">Justification obligatoire<textarea id="justification" placeholder="Motif de la décision managériale"></textarea></label>':'')+'<div class="actions"><button data-action="close-modal">Annuler</button><button class="primary" id="confirm-action">Confirmer</button></div>',()=>{$('#confirm-action').onclick=()=>{const reason=$('#justification')?.value||'';if(justify&&!reason.trim()){toast('Renseignez la justification.',true);return}closeModal();callback(reason)}})}
function closeDrawer(){$('#drawer-root').innerHTML='';selected=null;editing=null}
function openCase(id){const d=state.cases.find(d=>d.id===id);if(!d)return;if(view==='agent'){agentLoadedId=d.id;agentEditing=structuredClone(d);draftRevision=storageRevision;renderAgent();return}selected=id;editing=structuredClone(d);draftRevision=storageRevision;renderDrawer()}
function locationField(d,key,label){const p=d[key];return '<div class="location-field"><div><b style="font-size:11px">'+label+'</b><button type="button" class="small ghost" data-action="locate" data-field="'+key+'">'+icon('search')+' Localiser</button></div><p>'+esc(p?.label||'Non renseigné')+'</p><small>'+esc(hasPoint(p)?p.lat.toFixed(5)+', '+p.lng.toFixed(5)+' · '+(p.source||'Position confirmée'):'Sans coordonnées confirmées')+'</small></div>'}
function groupForm(d){return d.groups.map((g,i)=>'<div class="group-box" data-group="'+i+'"><div class="actions"><input aria-label="Nom du groupe '+(i+1)+'" name="g'+i+'_name" value="'+esc(g.name)+'" style="flex:1">'+(d.groups.length>1?'<button type="button" class="small ghost" data-action="remove-group" data-index="'+i+'" aria-label="Retirer le groupe '+(i+1)+'">'+icon('close')+'</button>':'')+'</div><div class="group-numbers">'+[['men','Hommes'],['women','Femmes'],['children','Enfants'],['vulnerable','Vulnérables*'],['animals','Animaux']].map(([k,l])=>'<label>'+icon(k==='children'?'child':k==='animals'?'pet':k==='vulnerable'?'shield':'person')+l+'<input aria-label="'+l+' groupe '+(i+1)+'" name="g'+i+'_'+k+'" type="number" min="0" max="1000" value="'+g[k]+'"></label>').join('')+'</div>'+select('Situation du groupe','g'+i+'_status',options(BENEFITS,g.status))+'</div>').join('')+'<small class="muted">* Les personnes vulnérables sont incluses dans la composition du groupe.</small>'}
function renderDrawer(){if(!editing)return;const d=editing,pri=priority(d,state.settings);$('#drawer-root').innerHTML='<div class="drawer-shade" data-action="close-drawer"></div><aside class="drawer" role="dialog" aria-modal="true" aria-label="Dossier '+esc(d.id)+'"><header class="drawer-head"><div><div class="eyebrow">Dossier ETR · '+(d.archived?'Archivé':'Actif')+'</div><h1>'+esc(d.id)+'</h1><small class="muted">Ouvert le '+date(d.opened)+' · '+age(d)+'</small></div><div class="actions">'+badge(d)+'<button class="ghost" data-action="close-drawer" aria-label="Fermer la fiche">'+icon('close')+'</button></div></header><div class="drawer-body"><form id="detail-form"><div class="section-title">Situation opérationnelle</div><div class="form-grid">'+select('Pays','country',countryOptions(d.country))+select('Assistance','type',options(['Panne','Accident'],d.type))+field('Ouverture (heure de Paris)','opened','datetime-local',isoLocal(new Date(d.opened)))+select('Étape du véhicule','stage',options(STAGES,d.stage))+select('Transport de véhicule','tvh',options(TVH,d.tvh))+'</div><div class="section-title">Localisation confirmée</div><div style="display:grid;gap:9px">'+locationField(d,'location','Lieu d’immobilisation')+locationField(d,'depot','Dépôt / garage')+locationField(d,'destination','Relivraison du véhicule')+locationField(d,'beneficiaryDestination','Destination des bénéficiaires')+'</div><div class="section-title">Bénéficiaires · '+people(d)+' personnes <button type="button" class="small ghost" data-action="add-group">'+icon('plus')+' Sous-groupe</button></div>'+groupForm(d)+'<div class="section-title">Responsabilités & prochaine action</div><div class="form-grid">'+select('Chargé responsable','agent',agentOptions(d.agent))+select('Langue requise','language',Object.entries(LANGUAGES).map(([k,v])=>opt(k,v,d.language)).join(''))+'<label class="field full">Chargés associés<select name="associates" multiple size="3">'+state.agents.map(a=>'<option value="'+a.id+'" '+(d.associates.includes(a.id)?'selected':'')+'>'+esc(a.name)+'</option>').join('')+'</select></label>'+field('Prochaine action','action','text',d.action,'class="full"')+field('Échéance (heure de Paris)','due','datetime-local',d.due?isoLocal(new Date(d.due)):'')+select('Responsable de l’action','actionOwner',agentOptions(d.actionOwner))+'</div><div class="section-title">Priorité de supervision</div><div class="form-grid">'+select('Attribution','priorityMode',options(['auto','manual'],d.priorityMode).replace('>auto<','>Automatique<').replace('>manual<','>Manuelle<'))+select('Niveau manuel','priority',Object.entries(PRIORITIES).map(([k,p])=>opt(k,p.label,d.priority)).join(''))+'<label class="field full">Motif manuel<input name="priorityReason" value="'+esc(d.priorityReason)+'" placeholder="Obligatoire pour un changement manuel"></label></div><div class="notice">Priorité actuelle : '+PRIORITIES[pri.key].label+' · '+esc(pri.reason)+'</div><label class="field">Commentaires opérationnels<textarea name="notes">'+esc(d.notes)+'</textarea></label><div class="section-title">Historique horodaté</div><div class="history">'+[...d.history].reverse().map(h=>'<div class="history-item"><small>'+date(h.at)+'</small>'+esc(h.text)+'</div>').join('')+'</div></form></div><footer class="drawer-foot"><button data-action="'+(d.archived?'reopen':'archive')+'" data-id="'+esc(d.id)+'">'+icon(d.archived?'plus':'archive')+' '+(d.archived?'Réouvrir':'Archiver')+'</button><button class="primary" data-action="save-case">'+icon('check')+' Enregistrer</button></footer></aside>'}
function fromParis(v){if(!v)return null;const raw=new Date(v+'Z');let result=raw;for(let i=0;i<2;i++){const parts=isoLocal(result);const difference=Date.parse(parts+'Z')-Date.parse(v+'Z');result=new Date(+result-difference)}return result.toISOString()}
function readForm(d,form){const f=new FormData(form);for(const k of ['country','type','stage','tvh','agent','language','action','actionOwner','priorityMode','priority','priorityReason','notes'])if(f.has(k))d[k]=String(f.get(k));if(f.has('due'))d.due=fromParis(f.get('due'));if(f.has('opened'))d.opened=fromParis(f.get('opened'));if(f.has('associates'))d.associates=f.getAll('associates');else if(form.id==='detail-form')d.associates=[];
 d.groups=d.groups.map((g,i)=>{const n={...g};for(const k of ['men','women','children','vulnerable','animals'])if(f.has('g'+i+'_'+k))n[k]=Number(f.get('g'+i+'_'+k));for(const k of ['name','status'])if(f.has('g'+i+'_'+k))n[k]=String(f.get('g'+i+'_'+k));return n});return d;
}
function capture(){if(view==='agent'&&agentEditing&&$('#agent-form')){readForm(agentEditing,$('#agent-form'));agentEditing.id=normalizeId($('#agent-id').value);}else if(editing&&$('#detail-form'))readForm(editing,$('#detail-form'))}
function persistDraft(d,isNew=false){
 try{const original=state.cases.find(x=>x.id===normalizeId(d.id));if(draftRevision!==storageRevision&&!isNew)throw Error('Les données ont changé dans une autre fenêtre. Rouvrez le dossier avant de sauvegarder pour éviter d’écraser une mise à jour.');if(isNew&&original)throw Error('Ce dossier est déjà enregistré.');
 const candidate=structuredClone(d);candidate.id=normalizeId(candidate.id);if(!people(candidate))throw Error('Renseignez au moins un bénéficiaire.');if(candidate.priorityMode==='manual'&&!candidate.priorityReason.trim())throw Error('Indiquez le motif de la priorité manuelle.');
 if(original&&candidate.stage!==original.stage){const temp=structuredClone(candidate);temp.stage=original.stage;moveStage(temp,candidate.stage)}
 if(candidate.tvh!=='Non applicable'&&!hasPoint(candidate.depot)&&!hasPoint(candidate.location))toast('TVH enregistré sans lieu de prise en charge confirmé.');
 const a=state.agents.find(a=>a.id===candidate.agent),warnings=a&&(!original||original.agent!==candidate.agent)?assignmentWarnings(state,candidate,a):[];
 const apply=reason=>{try{
 const next=structuredClone(state);let target=next.cases.find(x=>x.id===candidate.id);
 if(!target){target=createCase(next,{id:candidate.id,country:candidate.country,type:candidate.type});candidate.history=target.history;candidate.opened=target.opened}
 const previousPriority=priority(target,next.settings);const prevAgent=target.agent;const prevStage=target.stage,prevTVH=target.tvh,prevGroups=JSON.stringify(target.groups);
 const oldHistory=target.history;Object.assign(target,candidate);target.history=oldHistory;
 if(prevAgent!==candidate.agent){target.agent=prevAgent;assign(next,target,candidate.agent,reason);target.actionOwner=candidate.actionOwner||candidate.agent}
 if(prevStage!==candidate.stage)record(target,'Étape véhicule : '+prevStage+' → '+candidate.stage);
 if(prevTVH!==candidate.tvh)record(target,'TVH : '+prevTVH+' → '+candidate.tvh);
 if(prevGroups!==JSON.stringify(candidate.groups))record(target,'Mise à jour des bénéficiaires : '+target.groups.map(g=>g.name+' — '+g.status).join(' ; '));
 const nextPriority=priority(target,next.settings);if(previousPriority.key!==nextPriority.key||target.priorityMode!==original?.priorityMode)record(target,'Priorité : '+PRIORITIES[previousPriority.key].label+' → '+PRIORITIES[nextPriority.key].label+' · '+nextPriority.reason);
 record(target,'Fiche enregistrée · prochaine action : '+target.action);validateState(next);state=next;closeDrawer();if(view==='agent'){agentLoadedId=target.id;agentEditing=structuredClone(target);}commit('Dossier '+target.id+' enregistré');draftRevision=storageRevision;
 }catch(e){toast(e.message,true)}};
 validateState({...structuredClone(state),cases:[...state.cases.filter(x=>x.id!==candidate.id),candidate]});if(warnings.length)confirmAction('Affectation exceptionnelle',warnings.join(' · '),apply,true);else apply('');
 }catch(e){toast(e.message,true)}
}
function locate(key,mapOnly=false){capture();const d=view==='agent'?agentEditing:editing;const current=d?.[key];showModal('<h2>'+ (mapOnly?'Rechercher sur la carte':'Localiser et confirmer')+'</h2><p>Adresse, nom d’établissement ou GPS « latitude, longitude ». La recherche externe se lance uniquement avec le bouton Rechercher.</p><form id="place-form"><label class="field">Pays<select id="place-country">'+countryOptions(d?.country||filters.country||'',true)+'</select></label><label class="field">Lieu<input id="place-query" placeholder="Adresse, établissement ou 48.8566, 2.3522" value="'+esc(current?.label||'')+'" autocomplete="off"></label><button class="primary" type="submit">'+icon('search')+' Rechercher</button></form><div id="place-status" class="muted" style="font-size:11px;margin-top:12px"></div><div id="place-results" class="results"></div><div class="actions">'+(!mapOnly?'<button id="unlocated">Conserver comme non localisé</button>':'')+'<button data-action="close-modal">Fermer</button></div>',()=>{
 let resultSet=[];const choose=p=>{if(mapOnly){map?.map?.setView([p.lat,p.lng],15);if(window.L&&map?.map)L.popup().setLatLng([p.lat,p.lng]).setContent(esc(p.label)).openOn(map.map)}else{d[key]=p;if(p.country&&key==='location'&&COUNTRIES.some(c=>c.code===p.country))d.country=p.country;view==='agent'?renderAgent():renderDrawer()}closeModal();toast(mapOnly?'Lieu affiché':'Emplacement confirmé')};
 $('#place-form').onsubmit=async e=>{e.preventDefault();const btn=$('button[type=submit]',$('#place-form'));btn.disabled=true;$('#place-status').textContent='Recherche en cours…';try{resultSet=await searchPlace($('#place-query').value,$('#place-country').value);$('#place-results').innerHTML=resultSet.map((p,i)=>'<button class="result" data-result="'+i+'">'+esc(p.label)+'<small>'+p.lat.toFixed(5)+', '+p.lng.toFixed(5)+' · '+esc(p.source)+' · Cliquer pour confirmer</small></button>').join('');$('#place-status').textContent=resultSet.length+' résultat(s) à confirmer';$$('[data-result]').forEach(b=>b.onclick=()=>choose(resultSet[+b.dataset.result]))}catch(e){$('#place-status').textContent=e.message;$('#place-results').innerHTML=''}finally{btn.disabled=false}};
 if($('#unlocated'))$('#unlocated').onclick=()=>{const q=$('#place-query').value.trim();if(!q){toast('Saisissez le lieu à conserver.',true);return}d[key]={label:q,lat:null,lng:null,country:$('#place-country').value||d.country,source:'Texte saisi · non localisé'};closeModal();view==='agent'?renderAgent():renderDrawer();toast('Lieu conservé sans coordonnées')};
 })}
function defaultAgentDraft(){const t={cases:[]};const d=createCase(t,{id:'NEW',country:'FR'});d.id='';return d}
function renderAgent(){
 if(!agentEditing)agentEditing=defaultAgentDraft();const d=agentEditing,isExisting=agentLoadedId===d.id;
 $('#app').innerHTML='<main class="agent-page"><div class="brand"><div class="brand-symbol" style="color:white">'+icon('chart')+'</div><div><b>Manager Control</b><small class="muted" style="display:block">Interface chargé · démonstration</small></div></div><h1>Saisie rapide</h1><p class="muted" style="font-size:11px;margin-top:5px">Créer un dossier ou mettre à jour un statut.</p><div class="panel"><div class="panel-content"><form id="agent-form"><label class="field">Numéro de dossier<div class="inline-search"><input id="agent-id" name="id" value="'+esc(d.id)+'" placeholder="Ex. 826431" required autocomplete="off"><button type="button" data-action="find-agent-case" aria-label="Retrouver le dossier">'+icon('search')+'</button></div></label><div id="duplicate">'+(isExisting?'Dossier existant ouvert pour mise à jour.':'')+'</div><div class="form-grid" style="margin-top:14px">'+select('Pays','country',countryOptions(d.country))+select('Assistance','type',options(['Panne','Accident'],d.type))+field('Nombre de personnes','total','number',people(d),'min="1" max="1000" id="quick-total"')+select('Statut véhicule','stage',options(STAGES,d.stage))+select('TVH applicable / statut','tvh',options(TVH,d.tvh))+select('Bénéficiaires · groupe principal','quickStatus',options(BENEFITS,d.groups[0].status))+'</div><div style="margin-top:12px">'+locationField(d,'location','Lieu de panne / accident')+'</div>'+field('Prochaine action','action','text',d.action,'style="margin-top:12px"')+'<details><summary>Composition, dépôt, relivraison et échéance</summary><div class="groups">'+groupForm(d)+'</div><div style="display:grid;gap:9px;margin-top:14px">'+locationField(d,'depot','Dépôt / garage')+locationField(d,'destination','Relivraison du véhicule')+locationField(d,'beneficiaryDestination','Destination des bénéficiaires')+'</div><div class="form-grid" style="margin-top:12px">'+field('Échéance (Paris)','due','datetime-local',d.due?isoLocal(new Date(d.due)):'')+select('Chargé','agent',agentOptions(d.agent))+'</div><label class="field" style="margin-top:12px">Commentaires<textarea name="notes">'+esc(d.notes)+'</textarea></label></details><button type="submit" class="primary full">'+icon('check')+' ENREGISTRER</button></form><div class="actions" style="margin-top:12px"><button class="small ghost" data-action="new-agent">Nouveau dossier</button><a href="./" target="_blank" style="font-size:11px">Ouvrir la supervision ↗</a></div></div></div><div class="notice">Données fictives uniquement. Sauvegarde locale ; les onglets de ce même navigateur partagent les modifications. Aucune synchronisation entre appareils.</div><small class="muted">Ajoutez cette adresse aux favoris ou installez l’application depuis le menu du navigateur.</small></main>';
 $('#agent-form').onsubmit=e=>{e.preventDefault();capture();const typed=normalizeId($('#agent-id').value);if((!agentLoadedId||typed!==agentLoadedId)&&state.cases.some(x=>normalizeId(x.id)===typed)){toast('Ce dossier est déjà enregistré. Ouvrez le dossier existant.',true);return}if(agentLoadedId&&typed!==agentLoadedId){toast('Le numéro d’un dossier existant ne peut pas être modifié. Utilisez Nouveau dossier.',true);return}agentEditing.id=typed;persistDraft(agentEditing,!agentLoadedId)};
 $('#agent-id').oninput=e=>{const id=normalizeId(e.target.value),exists=state.cases.some(x=>normalizeId(x.id)===id);$('#duplicate').innerHTML=exists&&id!==agentLoadedId?'Ce dossier est déjà enregistré. <button type="button" class="link-button" data-action="find-agent-case">Ouvrir le dossier existant</button>':exists?'Dossier existant ouvert pour mise à jour.':''};
 $('#quick-total').onchange=e=>{capture();const n=Number(e.target.value);if(!Number.isInteger(n)||n<1)return;const g=agentEditing.groups[0],others=people(agentEditing)-g.men-g.women-g.children;if(n<others+g.women+g.children){toast('Modifiez la composition détaillée pour réduire ce total.',true);e.target.value=people(agentEditing);return}g.men=n-others-g.women-g.children;renderAgent()};
}
function download(name,text,type='application/json'){const blob=new Blob([text],{type}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function settings(){showModal('<h2>Paramètres & données</h2><p>Laboratoire local en données fictives. Ces réglages ne créent aucun accès multi-utilisateur.</p><form id="rules-form"><div class="form-grid">'+field('Sans progression : signaler après (h)','staleHours','number',state.settings.staleHours,'min="1" max="8760"')+field('Retard : urgent après (h)','urgentHours','number',state.settings.urgentHours,'min="1" max="8760"')+field('Retard : critique après (h)','criticalHours','number',state.settings.criticalHours,'min="1" max="8760"')+'</div><div class="actions"><button type="submit" class="primary">Enregistrer les règles</button></div></form><div class="section-title">Sauvegarde de démonstration</div><div class="actions" style="justify-content:flex-start"><button data-action="export">'+icon('download')+' Export JSON</button><button id="import-json-button">'+icon('upload')+' Import JSON</button><input type="file" accept=".json,application/json" id="import-json" hidden><button class="danger" data-action="reset-demo">Réinitialiser la démonstration</button></div><div class="section-title">Accès rapide</div><div class="actions" style="justify-content:flex-start"><button data-action="agent-window">'+icon('window')+' Ouvrir l’interface chargé</button><button data-action="install">Installer la PWA</button></div><div class="notice">Carte routière : Esri World Street Map (Esri, HERE, Garmin, USGS, NGA). Recherche : Nominatim, sur validation explicite, sans autocomplétion réseau. Routage : démonstration publique OSRM, sans garantie de disponibilité. Les positions initiales sont des repères de villes publiques, jamais des garages réels.</div><div class="actions"><button data-action="close-modal">Fermer</button></div>',()=>{
 $('#rules-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const cfg=Object.fromEntries(['staleHours','urgentHours','criticalHours'].map(k=>[k,Number(f.get(k))]));try{const next=structuredClone(state);next.settings=cfg;validateState(next);for(const d of next.cases){const a=priority(d,state.settings),b=priority(d,cfg);if(a.key!==b.key)record(d,'Règles de supervision modifiées : '+PRIORITIES[a.key].label+' → '+PRIORITIES[b.key].label+' · '+b.reason)}state=next;closeModal();commit('Règles enregistrées')}catch(e){toast(e.message,true)}};
 $('#import-json-button').onclick=()=>$('#import-json').click();$('#import-json').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>15*1024*1024)throw Error('Fichier trop volumineux (15 Mo maximum).');const imported=validateState(JSON.parse(await file.text()));confirmAction('Importer cette démonstration ?',imported.cases.length+' dossiers et '+imported.agents.length+' chargés remplaceront les données locales actuelles. Exportez-les d’abord si nécessaire.',()=>{state=imported;closeDrawer();agentEditing=null;agentLoadedId=null;commit('Données de démonstration importées')})}catch(e){toast(e.message,true)}};
 })}
function requestArchive(id){const d=state.cases.find(d=>d.id===id);if(!d)return;if(!ready(d)){toast('Terminez le parcours du véhicule et de tous les bénéficiaires avant l’archivage.',true);return}confirmAction('Archiver le dossier '+id+' ?','Il quittera les vues actives et restera disponible dans Archives avec son historique.',()=>{archive(d);closeDrawer();commit('Dossier archivé')})}
function requestAssign(id,agentId){const d=state.cases.find(d=>d.id===id);if(!d||d.archived)return;const a=state.agents.find(a=>a.id===agentId);const warnings=a?assignmentWarnings(state,d,a):[];const apply=reason=>{try{assign(state,d,agentId,reason);commit('Dossier '+id+' affecté à '+agentName(agentId))}catch(e){toast(e.message,true)}};if(warnings.length)confirmAction('Affectation exceptionnelle · '+agentName(agentId),warnings.join(' · '),apply,true);else apply('')}
function editShift(id){const a=state.agents.find(a=>a.id===id),sh=a.schedule.find(s=>s.date===planningDate)||{date:planningDate,start:'08:00',end:'17:00',breakStart:'12:00',breakEnd:'13:00',unavailable:false,reason:''};showModal('<h2>'+esc(a.name)+'</h2><p>Planning du '+planningDate+' · heure de Paris. Pour un poste de nuit, la date est celle de la prise de poste.</p><form id="shift-form"><div class="form-grid">'+field('Prise de poste','start','time',sh.start,'required')+field('Fin de service','end','time',sh.end,'required')+field('Début pause','breakStart','time',sh.breakStart,'required')+field('Fin pause','breakEnd','time',sh.breakEnd,'required')+'</div><label class="check-line" style="margin-top:16px"><input type="checkbox" name="unavailable" '+(sh.unavailable?'checked':'')+'> Indisponible / repos</label>'+field('Motif de l’indisponibilité','reason','text',sh.reason)+'<div class="actions"><button type="button" data-action="close-modal">Annuler</button><button type="submit" class="primary">Enregistrer</button></div></form>',()=>{$('#shift-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),next=structuredClone(state),agent=next.agents.find(x=>x.id===id);const updated={date:planningDate,start:f.get('start'),end:f.get('end'),breakStart:f.get('breakStart'),breakEnd:f.get('breakEnd'),unavailable:f.has('unavailable'),reason:f.get('reason')};agent.schedule=agent.schedule.filter(s=>s.date!==planningDate);agent.schedule.push(updated);try{validateState(next);state=next;closeModal();commit('Planning enregistré')}catch(e){toast(e.message,true)}}})}
function editAgent(id){const a=state.agents.find(a=>a.id===id);showModal('<h2>Profil du chargé</h2><p>Collaborateur fictif · langues réellement utilisées pour les contrôles d’affectation.</p><form id="profile-form"><div class="form-grid">'+field('Nom fictif','name','text',a.name,'required')+field('Service','service','text',a.service,'required')+field('Capacité indicative (dossiers)','capacity','number',a.capacity,'min="1" max="200" required')+'</div><div class="tags">'+Object.entries(LANGUAGES).map(([l,name])=>'<label class="check-line"><input type="checkbox" name="languages" value="'+l+'" '+(a.languages.includes(l)?'checked':'')+'>'+name+'</label>').join('')+'</div><div class="actions"><button type="button" data-action="close-modal">Annuler</button><button type="submit" class="primary">Enregistrer</button></div></form>',()=>{$('#profile-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);if(!f.getAll('languages').length){toast('Attribuez au moins une langue.',true);return}Object.assign(a,{name:String(f.get('name')),service:String(f.get('service')),capacity:Number(f.get('capacity')),languages:f.getAll('languages')});closeModal();commit('Profil enregistré')}})}
function handover(id){const a=state.agents.find(a=>a.id===id),rows=active(state).filter(d=>d.agent===id);showModal('<h2>Transmission · '+esc(a.name)+'</h2><p>'+rows.length+' dossiers actifs. Vérifiez le relais et les prochaines échéances.</p><label class="field">Chargé relais<select id="handover-agent">'+state.agents.filter(x=>x.id!==id).map(x=>opt(x.id,x.name,'')).join('')+'</select></label><div class="results">'+rows.map(d=>'<div class="notice"><b>'+d.id+' · '+d.stage+'</b><br>'+esc(d.action)+' · '+date(d.due)+'</div>').join('')+'</div><div class="actions"><button data-action="close-modal">Fermer</button><button id="handover-apply" class="primary" '+(!rows.length?'disabled':'')+'>Transmettre les dossiers</button></div>',()=>{$('#handover-apply').onclick=()=>{const target=$('#handover-agent').value,b=state.agents.find(x=>x.id===target),warnings=rows.flatMap(d=>assignmentWarnings(state,d,b).map(w=>d.id+' : '+w));const nextLoad=active(state).filter(d=>d.agent===target).length+rows.length;if(nextLoad>b.capacity)warnings.push('Charge après transmission : '+nextLoad+' dossiers / repère '+b.capacity);confirmAction('Confirmer la transmission à '+b.name,warnings.length?warnings.join(' · '):'Les prochaines actions et les historiques seront conservés.',reason=>{for(const d of rows){assign(state,d,target,reason||'Transmission de poste validée');record(d,'Transmission entre équipes : '+a.service+' → '+b.service)}commit('Transmission de '+rows.length+' dossiers enregistrée')},warnings.length>0)}})}
function planningTemplate(){download('manager-control-planning-modele.csv','agent_id;date;start;end;break_start;break_end;unavailable;reason\n'+state.agents.slice(0,3).map(a=>a.id+';'+planningDate+';08:00;17:00;12:00;13:00;false;').join('\n'),'text/csv;charset=utf-8')}
function importPlanning(){showModal('<h2>Importer un planning fictif</h2><p>CSV (virgule ou point-virgule) ou Excel .xlsx/.xls. Colonnes : agent_id, date (AAAA-MM-JJ), start, end, break_start, break_end, unavailable, reason. Le modèle CSV est disponible dans la page Équipes.</p><label class="field">Fichier de démonstration<input type="file" id="planning-file" accept=".csv,.xlsx,.xls"></label><div id="planning-import-result"></div><div class="actions"><button data-action="close-modal">Fermer</button></div>',()=>{$('#planning-file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>5*1024*1024)throw Error('Fichier trop volumineux (5 Mo maximum).');if(!window.XLSX)throw Error('Lecteur Excel indisponible. Rechargez l’application.');const wb=XLSX.read(await file.arrayBuffer(),{type:'array',cellDates:false,raw:true});const rows=XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]],{raw:true,defval:''});if(!rows.length||rows.length>10000)throw Error('Le planning doit contenir entre 1 et 10 000 lignes.');const next=structuredClone(state),errors=[],changed=[];const seen=new Set();
 const norm=k=>k.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[\s-]+/g,'_');
 for(let i=0;i<rows.length;i++){const r=Object.fromEntries(Object.entries(rows[i]).map(([k,v])=>[norm(k),String(v).trim()]));const a=next.agents.find(a=>a.id===r.agent_id||a.name.toLowerCase()===String(r.agent||r.nom||r.collaborateur).toLowerCase());let dt=r.date;if(/^\d+(\.\d+)?$/.test(dt)&&Number(dt)>20000){const parsed=XLSX.SSF.parse_date_code(Number(dt));if(parsed)dt=String(parsed.y)+'-'+String(parsed.m).padStart(2,'0')+'-'+String(parsed.d).padStart(2,'0')}else if(/^\d{1,2}\/\d{1,2}\/\d{4}$/.test(dt)){const [d,m,y]=dt.split('/');dt=y+'-'+m.padStart(2,'0')+'-'+d.padStart(2,'0')}const validTime=v=>{if(/^0?\.\d+$/.test(v)){const n=Math.round(Number(v)*1440);return String(Math.floor(n/60)%24).padStart(2,'0')+':'+String(n%60).padStart(2,'0')}if(/^\d{1,2}:\d{2}(:\d{2})?$/.test(v))return v.split(':').slice(0,2).map(x=>x.padStart(2,'0')).join(':');return v};const sh={date:dt,start:validTime(r.start||r.debut||''),end:validTime(r.end||r.fin||''),breakStart:validTime(r.break_start||r.pause_debut||'00:00'),breakEnd:validTime(r.break_end||r.pause_fin||'00:00'),unavailable:['true','1','oui','yes'].includes((r.unavailable||r.indisponible||'').toLowerCase()),reason:r.reason||r.motif||''};const key=a?.id+'|'+dt;if(!a||seen.has(key)||!/^\d{4}-\d{2}-\d{2}$/.test(dt)||!['start','end','breakStart','breakEnd'].every(k=>/^([01]\d|2[0-3]):[0-5]\d$/.test(sh[k]))||sh.start===sh.end){errors.push('Ligne '+(i+2)+' : collaborateur, date, horaires ou doublon invalide.');continue}seen.add(key);a.schedule=a.schedule.filter(s=>s.date!==dt);a.schedule.push(sh);changed.push(a.name+' · '+dt+' · '+sh.start+' – '+sh.end)}
 if(errors.length)throw Error(errors.slice(0,8).join(' '));validateState(next);$('#planning-import-result').innerHTML='<div class="notice">'+changed.length+' journées valides. Aucun changement avant confirmation.</div><p style="font-size:11px">'+changed.slice(0,8).map(esc).join('<br>')+'</p><button class="primary" id="apply-planning" style="margin-top:15px">Confirmer l’import</button>';$('#apply-planning').onclick=()=>{state=next;closeModal();commit(changed.length+' journées importées')};
 }catch(e){$('#planning-import-result').innerHTML='<div class="notice error">'+esc(e.message)+'</div>'}}})}
let installPrompt=null;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});
document.addEventListener('click',e=>{
 if(suppressClick){e.preventDefault();suppressClick=false;return}
 const v=e.target.closest('[data-view]');if(v){e.preventDefault();setView(v.dataset.view);return}
 const op=e.target.closest('[data-open]');if(op){closeModal();openCase(op.dataset.open);return}
 const el=e.target.closest('[data-action]');if(!el)return;const action=el.dataset.action,id=el.dataset.id;
 if(action==='close-modal'){closeModal();return}if(action==='close-drawer'){closeDrawer();return}
 if(action==='new'){showModal('<h2>Nouveau dossier</h2><p>Un identifiant unique suffit pour commencer. La fiche pourra être enrichie progressivement.</p><form id="new-form">'+field('Numéro de dossier','id','text','','required autocomplete="off"')+'<div id="new-duplicate" class="notice warn" hidden></div>'+select('Pays','country',countryOptions('FR'))+select('Assistance','type',options(['Panne','Accident'],'Panne'))+'<div class="actions"><button type="button" data-action="close-modal">Annuler</button><button class="primary" type="submit">Créer le dossier</button></div></form>',()=>{const form=$('#new-form'),number=$('[name=id]',form);number.oninput=()=>{const d=state.cases.find(d=>normalizeId(d.id)===normalizeId(number.value)),msg=$('#new-duplicate');msg.hidden=!d;msg.innerHTML=d?'Ce dossier est déjà enregistré. <button type="button" class="link-button" data-open="'+d.id+'">Ouvrir le dossier existant</button>':''};form.onsubmit=e=>{e.preventDefault();try{const f=new FormData(form),d=createCase(state,Object.fromEntries(f));save();closeModal();render();openCase(d.id);toast('Dossier créé, complétez les informations utiles')}catch(e){toast(e.message,true)}}});return}
 if(action==='save-case'){capture();persistDraft(editing);return}
 if(action==='locate'){locate(el.dataset.field);return}if(action==='search-map'){locate('location',true);return}
 if(action==='add-group'||action==='remove-group'){capture();const d=view==='agent'?agentEditing:editing;if(action==='add-group')d.groups.push({id:'g'+Date.now(),name:'Sous-groupe '+(d.groups.length+1),men:1,women:0,children:0,vulnerable:0,animals:0,status:BENEFITS[2]});else if(d.groups.length>1)d.groups.splice(+el.dataset.index,1);view==='agent'?renderAgent():renderDrawer();return}
 if(action==='archive'){requestArchive(id);return}if(action==='reopen'){const d=state.cases.find(d=>d.id===id);confirmAction('Réouvrir le dossier '+id+' ?','Il rejoindra les dossiers actifs en prise en charge.',()=>{reopen(d);closeDrawer();commit('Dossier réouvert')});return}
 if(action==='reset-filters'){filters={country:'',agent:'',priority:'',stage:'',type:'',q:'',from:'',to:''};render();return}
 if(action==='dates'){showModal('<h2>Période des dossiers</h2><p>Date d’ouverture pour les vues actives ; date de clôture dans les archives.</p><form id="dates-form"><div class="form-grid">'+field('Du','from','date',filters.from)+field('Au','to','date',filters.to)+'</div><div class="actions"><button type="button" data-action="close-modal">Annuler</button><button type="submit" class="primary">Appliquer</button></div></form>',()=>{$('#dates-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);if(f.get('from')&&f.get('to')&&f.get('from')>f.get('to')){toast('La date de fin précède le début.',true);return}filters.from=f.get('from');filters.to=f.get('to');closeModal();render()}});return}
 if(action==='cases-list'||action==='cases-kanban'){dossierMode=action==='cases-list'?'list':'kanban';render();return}
 if(action==='teams-assign'||action==='teams-planning'){teamMode=action==='teams-assign'?'assign':'planning';render();return}
 if(action==='settings'){settings();return}
 if(action==='export'){download('manager-control-demo-'+parisDate()+'.json',JSON.stringify(state,null,2));toast('Export JSON préparé');return}
 if(action==='reset-demo'){confirmAction('Réinitialiser la démonstration ?','Les modifications locales seront remplacées par 72 nouveaux scénarios fictifs. Exportez-les auparavant si nécessaire.',()=>{state=seed();closeDrawer();agentEditing=null;agentLoadedId=null;commit('Démonstration réinitialisée')});return}
 if(action==='agent-window'){e.preventDefault();setView('agent');return}
 if(action==='new-agent'){agentLoadedId=null;agentEditing=defaultAgentDraft();draftRevision=storageRevision;renderAgent();return}
 if(action==='find-agent-case'){const id=normalizeId($('#agent-id').value);const d=state.cases.find(x=>normalizeId(x.id)===id);if(!d){toast('Aucun dossier enregistré sous ce numéro. Vous pouvez le créer.',true);return}closeModal();openCase(d.id);return}
 if(action==='edit-shift'){editShift(id);return}if(action==='edit-agent'){editAgent(id);return}if(action==='handover'){handover(id);return}
 if(action==='planning-template'){planningTemplate();return}if(action==='import-planning'){importPlanning();return}
 if(action==='install'){if(installPrompt){installPrompt.prompt();installPrompt=null}else toast('Dans le menu du navigateur, utilisez « Installer l’application » ou « Ajouter à l’écran d’accueil » si disponible.');return}
});
document.addEventListener('change',e=>{
 if(e.target.matches('[data-filter]')){filters[e.target.dataset.filter]=e.target.value;render();return}
 if(e.target.name==='quickStatus'){capture();agentEditing.groups[0].status=e.target.value;renderAgent();return}
 if(e.target.id==='completed'){completed=e.target.checked;map?.update(state,filtered(state,filters),view,{completed,flow:flowType});return}
 if(e.target.id==='flow-type'){flowType=e.target.value;map?.update(state,filtered(state,filters),view,{completed,flow:flowType});return}
 const ids={'agent-language':'language','agent-availability':'availability','agent-service':'service'};
 if(ids[e.target.id]){if(e.target.id==='agent-language')agentLanguage=e.target.value;if(e.target.id==='agent-availability')agentAvailability=e.target.value;if(e.target.id==='agent-service')agentService=e.target.value;render();return}
 if(e.target.id==='planning-date'){planningDate=e.target.value;render();return}
});
let searchTimer;document.addEventListener('input',e=>{if(e.target.matches('[data-filter=q]')){const value=e.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{filters.q=value;render();const input=$('[data-filter=q]');input?.focus();input?.setSelectionRange(value.length,value.length)},300)}if(e.target.id==='agent-query'){const value=e.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{agentQuery=value;render();$('#agent-query')?.focus()},300)}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if($('#modal-root').innerHTML)closeModal();else closeDrawer()}if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-open][role=button]')){e.preventDefault();openCase(e.target.dataset.open)}});
document.addEventListener('dragstart',e=>{if(pointerDrag){e.preventDefault();return}const c=e.target.closest('[data-case]');if(c){e.dataTransfer.setData('text/plain',c.dataset.case);e.dataTransfer.effectAllowed='move'}});
document.addEventListener('dragover',e=>{const t=e.target.closest('[data-drop]');if(t){e.preventDefault();t.classList.add('drop-over');e.dataTransfer.dropEffect='move'}});
document.addEventListener('dragleave',e=>{const t=e.target.closest('[data-drop]');if(t&&!t.contains(e.relatedTarget))t.classList.remove('drop-over')});
document.addEventListener('drop',e=>{const t=e.target.closest('[data-drop]');$$('.drop-over').forEach(x=>x.classList.remove('drop-over'));if(!t)return;e.preventDefault();const id=e.dataTransfer.getData('text/plain'),d=state.cases.find(x=>x.id===id);if(!d)return;if(t.dataset.drop==='archive')requestArchive(id);if(t.dataset.drop==='assign')requestAssign(id,t.dataset.agent);if(t.dataset.drop==='stage'){try{moveStage(d,t.dataset.stage);commit('Étape du véhicule mise à jour')}catch(e){toast(e.message,true)}}});
window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){try{state=validateState(JSON.parse(e.newValue));storageRevision++;if(view!=='agent')render();if(editing||view==='agent')toast('Données modifiées dans une autre fenêtre. Rouvrez le dossier avant de modifier.',true);else toast('Données actualisées depuis l’autre fenêtre')}catch{toast('Une modification externe est illisible et a été ignorée.',true)}}});
if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>toast('Installation hors ligne indisponible ; l’application reste utilisable en ligne.',true)));
render();

// Pointer-based dragging also supports touch screens and consistent browser automation.
function applyDrop(id,target){const d=state.cases.find(x=>x.id===id);if(!d||!target)return;if(target.dataset.drop==='archive')requestArchive(id);if(target.dataset.drop==='assign')requestAssign(id,target.dataset.agent);if(target.dataset.drop==='stage'){try{moveStage(d,target.dataset.stage);commit('Étape du véhicule mise à jour')}catch(e){toast(e.message,true)}}}
document.addEventListener('pointerdown',e=>{const card=e.target.closest('[data-case]');if(!card||e.button!==0)return;pointerDrag={id:card.dataset.case,x:e.clientX,y:e.clientY,card,ghost:null};});
document.addEventListener('pointermove',e=>{if(!pointerDrag)return;const p=pointerDrag;if(!p.ghost&&Math.hypot(e.clientX-p.x,e.clientY-p.y)>7){p.ghost=p.card.cloneNode(true);p.ghost.classList.add('drag-ghost');p.ghost.removeAttribute('data-case');document.body.append(p.ghost);document.body.classList.add('is-dragging');}if(!p.ghost)return;e.preventDefault();p.ghost.style.left=e.clientX+12+'px';p.ghost.style.top=e.clientY+8+'px';$$('.drop-over').forEach(x=>x.classList.remove('drop-over'));document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-drop]')?.classList.add('drop-over');},{passive:false});
document.addEventListener('pointerup',e=>{if(!pointerDrag)return;const p=pointerDrag;pointerDrag=null;if(!p.ghost)return;const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-drop]');p.ghost.remove();document.body.classList.remove('is-dragging');$$('.drop-over').forEach(x=>x.classList.remove('drop-over'));suppressClick=true;setTimeout(()=>suppressClick=false,100);applyDrop(p.id,target)});
document.addEventListener('pointercancel',()=>{pointerDrag?.ghost?.remove();pointerDrag=null;document.body.classList.remove('is-dragging');$$('.drop-over').forEach(x=>x.classList.remove('drop-over'))});
